using System.Collections.Generic;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EffectGainStatusDiceAction", menuName = "Data/Battle/Battle Actions/Enchantment Actions/EffectGainStatusDice Action")]
public class EffectGainStatusDiceAction : BattleAction
{
	[Header("Purify Gain Hex Die Action")]
	[SerializeField]
	private HexAction hexAction;

	[SerializeField]
	private BattleAction effectAction;

	[SerializeField]
	private bool amountAsStatusDiceAmount;

	[SerializeField]
	[ShowIf("amountAsStatusDiceAmount")]
	private int effectAmount;

	[SerializeField]
	private bool onlyAddIfNoHexDieOnDicePool;

	public HexAction HexAction => hexAction;

	public BattleAction EffectAction => effectAction;

	public bool AmountAsStatusDiceAmount => amountAsStatusDiceAmount;

	public int EffectAmount => effectAmount;

	public bool OnlyAddIfNoHexDieOnDicePool => onlyAddIfNoHexDieOnDicePool;

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		if (amountAsStatusDiceAmount)
		{
			effectAction.AreaCastTargetAmount(targets, effectAmount, source);
			if (!onlyAddIfNoHexDieOnDicePool || ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByTypeAmount(onlyFromHand: false)["Hex"] <= 0)
			{
				InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
				{
					hexAction.CastAmount(amount, source);
				});
			}
			return;
		}
		effectAction.AreaCastTargetAmount(targets, amount, source);
		if (!onlyAddIfNoHexDieOnDicePool || ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByTypeAmount(onlyFromHand: false)["Hex"] <= 0)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
			{
				hexAction.Cast(source);
			});
		}
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (amountAsStatusDiceAmount)
		{
			effectAction.CastTargetAmount(target, effectAmount, source);
			if (!onlyAddIfNoHexDieOnDicePool || ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByTypeAmount(onlyFromHand: false)["Hex"] <= 0)
			{
				InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
				{
					hexAction.CastAmount(amount, source);
				});
			}
			return;
		}
		effectAction.CastTargetAmount(target, amount, source);
		if (!onlyAddIfNoHexDieOnDicePool || ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByTypeAmount(onlyFromHand: false)["Hex"] <= 0)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
			{
				hexAction.Cast(source);
			});
		}
	}
}
